$module=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/FinanceAdminModule.php');$app=(string)file_get_contents($root.'/server/app/Application/Money/WebAdminFinance.php');$contract=(string)file_get_contents($root.'/server/app/Contracts/AdminFinanceRepository.php');$read=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminFinanceReadStore.php');$write=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminFinanceWriteStore.php');$facade=(string)file_get_contents($root.'/server/app/Infrastructure/Persistence/DatabaseAdminFinanceRepository.php');$kernel=(string)file_get_contents($root.'/server/app/Http/Admin/AdminKernel.php');$legacy=(string)file_get_contents($root.'/server/app/Http/Admin/Modules/LegacyAdminModule.php');
