$assert(strpos($write,'wall_worker_admin_demo_guard')!==false&&strpos($write,'SELECT GET_LOCK')!==false&&strpos($write,'SELECT RELEASE_LOCK')!==false,'legacy demo named-lock boundary lost');$assert(strpos($write,"\\setting('demo.data_enabled',true)")!==false,'demo enabled state is no longer checked after lock acquisition');foreach(['refunds.approve','wallets.recharge.refund','withdrawals.transition'] as $route)$assert(strpos($write,"'{$route}'")!==false,'demo marker query missing '.$route);$assert(strpos($write,'演示数据已关闭，该演示记录不可继续处理。')!==false,'demo write rejection changed');
